class VBase { int data_b; };

// Virtual inheritance introduces the vbptr (Virtual Base Pointer)
// The vbptr points to the shared VBase subobject offset.
class DerivedA : virtual public VBase { int data_a; };
class DerivedB : virtual public VBase { int data_c; };

class MostDerived : public DerivedA, public DerivedB {
    int data_m;
    // Memory layout typically includes:
    // 1. DerivedA subobject (includes vbptr_A)
    // 2. DerivedB subobject (includes vbptr_B)
    // 3. MostDerived specific data
    // 4. Single shared VBase subobject (at end/start depending on ABI)
};

